<script>
const list=document.getElementById('sectionList');
async function saveOrder(){const ids=[...list.querySelectorAll('[data-section]')].map(x=>Number(x.dataset.section));await fetch(@json(route('cbt.sections.reorder',$exam)),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':@json(csrf_token()),'Accept':'application/json'},body:JSON.stringify({section_ids:ids})});}
document.querySelectorAll('.move-up').forEach(b=>b.onclick=async e=>{e.preventDefault();const el=b.closest('[data-section]');if(el.previousElementSibling){list.insertBefore(el,el.previousElementSibling);await saveOrder();}});
document.querySelectorAll('.move-down').forEach(b=>b.onclick=async e=>{e.preventDefault();const el=b.closest('[data-section]');if(el.nextElementSibling){list.insertBefore(el.nextElementSibling,el);await saveOrder();}});
async function saveQuestionOrder(listEl){const ids=[...listEl.querySelectorAll('[data-question]')].map(x=>Number(x.dataset.question));await fetch(listEl.dataset.reorderUrl,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':@json(csrf_token()),'Accept':'application/json'},body:JSON.stringify({question_ids:ids})});}
document.querySelectorAll('.q-up').forEach(b=>b.onclick=async()=>{const row=b.closest('[data-question]'),box=row.closest('[data-question-list]');if(row.previousElementSibling){box.insertBefore(row,row.previousElementSibling);await saveQuestionOrder(box);}});document.querySelectorAll('.q-down').forEach(b=>b.onclick=async()=>{const row=b.closest('[data-question]'),box=row.closest('[data-question-list]');if(row.nextElementSibling){box.insertBefore(row.nextElementSibling,row);await saveQuestionOrder(box);}});
</script>
@endpush
